#include <cmath>
#include <cstdio>
#include <vector>

#define MAX 10001

using namespace std;

bool is_prime[MAX];

void ComputePrimes() {
    fill(is_prime, is_prime + MAX, true);
    is_prime[0] = is_prime[1] = false; // 0 and 1 are not prime numbers
    for (int i = 2; i * i < MAX; ++i) {
        if (is_prime[i]) {
            for (int j = i * i; j < MAX; j += i) {
                is_prime[j] = false;
            }
        }
    }
}

int main() {
    ComputePrimes();
    while (true) {
        int N, P = 0;
        if (scanf("%d", &N) == EOF) break;
        for (int i = 1; i <= N; ++i) {
            P += is_prime[N - i + 1] && is_prime[i];
        }
        printf("%d\n", P);
    }
    return 0;
}

